expected_daily_dates <- function(start_date, end_date) { start_date <- as.Date(start_date); end_date <- as.Date(end_date); if(start_date>end_date) as.Date(character()) else seq(start_date,end_date,by="day") }
find_missing_dates <- function(observed_dates,start_date,end_date) setdiff(expected_daily_dates(start_date,end_date), as.Date(observed_dates))
compress_dates_to_intervals <- function(dates) { d <- sort(unique(as.Date(dates))); if(!length(d)) return(data.frame(start=as.Date(character()), end=as.Date(character()))); z <- c(TRUE, diff(d)!=1); g <- cumsum(z); data.frame(start=as.Date(tapply(d,g,min)), end=as.Date(tapply(d,g,max))) }
split_dates_by_year_month <- function(dates) { d <- sort(unique(as.Date(dates))); if(!length(d)) return(data.frame(year=character(),month=character(),date=as.Date(character()))); data.frame(year=format(d,"%Y"), month=format(d,"%m"), date=d) }
plan_observed_update <- function(daily_inventory, initial_start_date, observed_end, overlap_days=14) {
  s <- summarize_grid_inventory(daily_inventory); end <- as.Date(observed_end); obs <- daily_inventory$date[daily_inventory$valid & !daily_inventory$estimated]; est <- daily_inventory$date[daily_inventory$valid & daily_inventory$estimated]; if(!length(obs)) { d <- expected_daily_dates(initial_start_date,end); reason <- rep("initial",length(d)) } else { d <- sort(unique(c(find_missing_dates(obs,min(as.Date(initial_start_date)),end), if(max(obs)<end) seq(max(obs)+1,end,by="day") else as.Date(character()), seq(max(min(obs),max(obs)-overlap_days+1),max(obs),by="day")))); reason <- ifelse(d %in% find_missing_dates(obs,min(as.Date(initial_start_date)),end),"internal_gap",ifelse(d<=max(obs),"overlap","new")); reason[d < min(obs)] <- "initial" }
  if(!length(d)) data.frame(date=as.Date(character()), reason=character(), represented_only_by_estimate=logical()) else data.frame(date=d, reason=reason, represented_only_by_estimate=d %in% est)
}
